update public.listings
set price = case id
  when 'a7777777-7777-4777-8777-777777777777' then 2
  when 'a9999999-9999-4999-8999-999999999999' then 3
  when 'a8888888-8888-4888-8888-888888888888' then 4
  when 'a3333333-3333-4333-8333-333333333333' then 5
  when 'b1111111-1111-4111-8111-111111111111' then 6
  else price
end
where id in (
  'a7777777-7777-4777-8777-777777777777',
  'a9999999-9999-4999-8999-999999999999',
  'a8888888-8888-4888-8888-888888888888',
  'a3333333-3333-4333-8333-333333333333',
  'b1111111-1111-4111-8111-111111111111'
);
